function validate([points]) {
  if (!Array.isArray(points) || points.length < 3 || points.length > 10000) return 'points needs 3 to 10000 vertices.';
  const seen = new Set();
  for (const p of points) {
    if (!Array.isArray(p) || p.length !== 2 || !Number.isInteger(p[0]) || !Number.isInteger(p[1])) return 'Each point is a pair [x, y] of whole numbers.';
    if (Math.abs(p[0]) > 10000 || Math.abs(p[1]) > 10000) return 'Coordinates are between -10^4 and 10^4.';
    const key = p[0] + ',' + p[1];
    if (seen.has(key)) return 'All points must be distinct.';
    seen.add(key);
  }
  const n = points.length;
  let turning = 0;
  for (let i = 0; i < n; i++) {
    const a = points[i], b = points[(i + 1) % n], c = points[(i + 2) % n];
    const ux = b[0] - a[0], uy = b[1] - a[1], vx = c[0] - b[0], vy = c[1] - b[1];
    const cross = ux * vy - uy * vx, dot = ux * vx + uy * vy;
    if (cross === 0 && dot < 0) return 'The outline must not double back on itself.';
    turning += Math.atan2(cross, dot);
  }
  // A simple polygon turns exactly once around in total.
  if (Math.abs(Math.abs(turning) - 2 * Math.PI) > 1e-6) return 'The points must form a simple polygon whose edges do not cross.';
  if (n <= 300) {
    const orient = (p, q, r) => Math.sign((q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0]));
    const within = (p, q, r) => Math.min(p[0], q[0]) <= r[0] && r[0] <= Math.max(p[0], q[0]) && Math.min(p[1], q[1]) <= r[1] && r[1] <= Math.max(p[1], q[1]);
    const meet = (p, q, r, s) => {
      const o1 = orient(p, q, r), o2 = orient(p, q, s), o3 = orient(r, s, p), o4 = orient(r, s, q);
      if (o1 * o2 < 0 && o3 * o4 < 0) return true;
      return (o1 === 0 && within(p, q, r)) || (o2 === 0 && within(p, q, s)) || (o3 === 0 && within(r, s, p)) || (o4 === 0 && within(r, s, q));
    };
    for (let i = 0; i < n; i++) {
      for (let j = i + 2; j < n; j++) {
        if (i === 0 && j === n - 1) continue;
        if (meet(points[i], points[(i + 1) % n], points[j], points[(j + 1) % n])) return 'The points must form a simple polygon whose edges do not cross.';
      }
    }
  }
  return null;
}

