function isConvex(points) {
  // A simple polygon is convex exactly when every vertex lies on one side of each edge's line.
  const n = points.length;
  for (let e = 0; e < n; e++) {
    const [px, py] = points[e];
    const [qx, qy] = points[(e + 1) % n];
    let left = false;
    let right = false;
    for (const [rx, ry] of points) {
      const side = (qx - px) * (ry - py) - (qy - py) * (rx - px);
      if (side > 0) left = true;
      if (side < 0) right = true;
    }
    if (left && right) return false;
  }
  return true;
}

