function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const finish = (points, room) => {
    const dx = int(-room, room), dy = int(-room, room);
    const shift = int(0, points.length - 1);
    const out = points.slice(shift).concat(points.slice(0, shift)).map(([x, y]) => [x + dx, y + dy]);
    if (rand() < 0.5) out.reverse();
    return [out];
  };
  // Convex: edge vectors sorted by angle, then their negations, walk once around a convex shape.
  const convex = (count, reach) => {
    for (;;) {
      const dirs = [];
      while (dirs.length < count) {
        const a = int(-reach, reach), b = int(0, reach);
        if (b > 0 || a > 0) dirs.push([a, b]);
      }
      dirs.sort((p, q) => q[0] * p[1] - q[1] * p[0]);
      if (dirs.every(d => d[0] * dirs[0][1] === d[1] * dirs[0][0])) continue;
      const points = [];
      let x = 0, y = 0;
      for (const [a, b] of dirs.concat(dirs.map(([a, b]) => [-a, -b]))) { points.push([x, y]); x += a; y += b; }
      const xs = points.map(p => p[0]), ys = points.map(p => p[1]);
      const mx = Math.round((Math.min(...xs) + Math.max(...xs)) / 2), my = Math.round((Math.min(...ys) + Math.max(...ys)) / 2);
      return points.map(([px, py]) => [px - mx, py - my]);
    }
  };
  // Star-shaped: points in distinct directions around the origin, sorted by angle, with every gap under half a turn.
  const star = (count, span) => {
    const gcd = (a, b) => (b ? gcd(b, a % b) : a);
    for (;;) {
      const byDirection = new Map();
      while (byDirection.size < count) {
        const x = int(-span, span), y = int(-span, span);
        if (x === 0 && y === 0) continue;
        const g = gcd(Math.abs(x), Math.abs(y));
        const key = x / g + ',' + y / g;
        if (!byDirection.has(key)) byDirection.set(key, [x, y]);
      }
      const points = [...byDirection.values()].sort((p, q) => Math.atan2(p[1], p[0]) - Math.atan2(q[1], q[0]));
      const angles = points.map(([x, y]) => Math.atan2(y, x));
      let widest = angles[0] + 2 * Math.PI - angles[angles.length - 1];
      for (let i = 1; i < angles.length; i++) widest = Math.max(widest, angles[i] - angles[i - 1]);
      if (widest < Math.PI - 1e-9) return points;
    }
  };
  // Convex hull (strict) of a few random points, for triangles and odd vertex counts.
  const hull = (count, span) => {
    for (;;) {
      const raw = Array.from({ length: count }, () => [int(-span, span), int(-span, span)]);
      const pts = [...new Map(raw.map(p => [p.join(','), p])).values()].sort((p, q) => p[0] - q[0] || p[1] - q[1]);
      const turn = (o, a, b) => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
      const half = list => {
        const chain = [];
        for (const p of list) {
          while (chain.length >= 2 && turn(chain[chain.length - 2], chain[chain.length - 1], p) <= 0) chain.pop();
          chain.push(p);
        }
        return chain.slice(0, -1);
      };
      const result = half(pts).concat(half(pts.slice().reverse()));
      if (result.length >= 3) return result;
    }
  };
  if (size === 'large') return rand() < 0.5 ? finish(convex(1000, 12), 2000) : finish(star(2000, 10000), 0);
  const mode = rand();
  if (mode < 0.3) return finish(convex(int(2, 4), 3), 3);
  if (mode < 0.55) return finish(hull(int(3, 8), 5), 3);
  return finish(star(int(3, 8), 5), 3);
}
